#' Import PNG files as pdr drawings
#'
#' Reads RGBA PNG files generated by custom software and converts them into
#' pdr_drawing elements (see [pdr_match()]), so that the rest of the paindrawR
#' pipeline can be used. The pixel data is stored in the `.rgba` element. Since
#' a PNG holds no stroke information, `.points` and `.strokes` are empty tibbles
#' with the expected column types.
#'
#' Only PNGs with four channels (RGBA) are accepted. Pixels that are fully
#' transparent are set to black (rather than transparent white). The row order
#' of `.rgba` is as returned by [png::readPNG()] (row 1 is the top of the image).
#'
#' @param files Character vector of paths to RGBA PNG files.
#' @param id_from_filename Logical. If `TRUE` (default), `.id` is the file name
#'   without directory and `.png` extension. If `FALSE`, `.id` is `NA_character_`.
#'
#' @returns A pdr_tibble (see [pdr_match()]; as from [pdr_import_json()]) with
#'   one row per file and columns `pdr_data` (a pdr_list of pdr_drawings, each
#'   containing `.id`, `.file`, `.version`, `.width`, `.height`, `.units`,
#'   `.timestamp`, `.app`, `.template_file`, `.points`, `.strokes` and `.rgba`) and `id`.
#'   `NA` entries in `files` give `NA` in `pdr_data` and `id`. Non-existing files
#'   give a warning and `NA` in `pdr_data`, with `id` derived from the file name
#'   (if `id_from_filename`).
#'
#' @export
#'
#' @examples
#' \dontrun{
#' pdr_tibble <- pdr_import_png(c("drawing_a.png", "drawing_b.png"))
#'
#' # Inspect the imported colours and alpha channel
#' pdr_plot_rgba(pdr_tibble)
#' pdr_plot_rgba(pdr_tibble, only_alpha = TRUE)
#' }
pdr_import_png <- function(files, id_from_filename = TRUE) {
  if (!is.character(files) || length(files) == 0) {
    stop("`files` must be a character vector of file paths.")
  }
  missing <- !is.na(files) & !file.exists(files)
  if (any(missing)) {
    warning(
      "Non-existing PNG files specified: ",
      paste(files[missing], collapse = ", ")
    )
  }

  pdr_data <- files |>
    purrr::map(\(file) {
      # NA in, NA out; non-existing files also give NA (row alignment is kept)
      if (is.na(file) || !file.exists(file)) {
        return(NA)
      }
      img <- png::readPNG(file)
      d <- dim(img)
      if (length(d) != 3 || d[3] != 4) {
        channels <- if (length(d) == 2) 1L else d[3]
        stop(
          "`",
          file,
          "` must be a four-channel RGBA PNG; found ",
          channels,
          " channel(s)."
        )
      }
      rgba <- img

      # Make transparent pixels black (rather than transparent white)
      rgba[,, 1:3][rgba[,, 4] == 0] <- 0

      list(
        .id = if (id_from_filename) {
          tools::file_path_sans_ext(basename(file))
        } else {
          NA_character_
        },
        .file = file,
        .version = NA_integer_,
        .width = dim(rgba)[2],
        .height = dim(rgba)[1],
        .units = "px",
        .timestamp = NA_character_,
        .app = NA_character_,
        .template_file = NA_character_,
        .points = tibble::tibble(
          .index = integer(),
          .x = integer(),
          .y = integer()
        ),
        .strokes = tibble::tibble(.index = integer()),
        .rgba = rgba
      )
    })

  tibble::tibble(
    pdr_data = pdr_data,
    id = purrr::map2_chr(
      pdr_data,
      files,
      \(x, file) {
        if (is.list(x)) {
          x$.id
        } else if (id_from_filename && !is.na(file)) {
          # Non-existing file: id still traceable from the path
          tools::file_path_sans_ext(basename(file))
        } else {
          NA_character_
        }
      }
    )
  )
}
